import os
import json

def transform_v2(grid):
    result = [list(row) for row in grid]
    for i, row in enumerate(result):
        by_val = {}
        for j, v in enumerate(row):
            if v != 0:
                if v not in by_val:
                    by_val[v] = (j, j)
                else:
                    by_val[v] = (by_val[v][0], j)
        for v, (first, last) in by_val.items():
            for j in range(first + 1, last):
                result[i][j] = 2
    return result

# Load current grids
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
G = os.path.normpath(d + '/../../sessions/' + os.path.basename(d) + '.jsonl')
t = open(G).read()

import re
all_grids = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in all_grids and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        all_grids[k] = [[int(x) for x in r] for r in rows]

# Test transform
for key in all_grids:
    grid = all_grids[key]
    result = transform_v2(grid)
    print(f"{key}:\n{json.dumps(grid)}\n->\n{json.dumps(result)}\n")

